def _safe_lines(s: Any) -> str:
    """_safe per line: newlines stay, other control/bidi characters become visible escapes."""
    return "\n".join(_safe(line) for line in str(s).split("\n"))

    def log(kind: str, msg: str) -> None:
        msg = _safe_lines(msg)
        if kind == "say":
            print(f"{CYAN}[에이전트]{RESET} {msg}", flush=True)
        elif kind == "call":
            print(f"{DIM}  → {msg}{RESET}", flush=True)
        elif kind == "result":
            lines = msg.splitlines()
            head = "\n".join(lines[:6]) + (f"\n… ({len(lines) - 6}줄 더)" if len(lines) > 6 else "")
            print(f"{DIM}{head}{RESET}", flush=True)
